package com.honorablemobile

import org.junit.runner.RunWith
import org.robolectric.RobolectricTestRunner
import org.robolectric.annotation.Config

import android.app.AlertDialog
import android.net.Uri
import app.honorable.editor.EditorAccessMode
import org.junit.Assert.*
import org.junit.Test

/** Real visible-approval/project mutation gates, with metadata-only dialog membership. */
@RunWith(RobolectricTestRunner::class)
@Config(sdk = [34], manifest = Config.NONE, application = android.app.Application::class)
class VideoTransformReviewTest {
 private val unsafe=JvmTestAllocator
 private fun set(a:Any,n:String,v:Any?)=a.javaClass.getDeclaredField(n).apply{isAccessible=true}.set(a,v)
 private fun get(a:Any,n:String)=a.javaClass.getDeclaredField(n).apply{isAccessible=true}.get(a)
 private fun call(a:Any,n:String,vararg args:Any?)=a.javaClass.declaredMethods.single{it.name==n&&it.parameterCount==args.size}.apply{isAccessible=true}.invoke(a,*args)
 private fun activity()=(unsafe.allocateInstance(HonorableVideoEditorActivity::class.java)as HonorableVideoEditorActivity).also{val p=VideoEditProject(5000);p.restore(listOf(VideoSegment(0,5000,captions=listOf(VideoCaption(0,500,"A"),VideoCaption(1000,1500,"B")),captionSourceUri="content://synthetic/subtitles")),soundtrack=VideoSoundtrack("content://synthetic/music",10000,loop=false));set(it,"project",p);set(it,"source",Uri.parse("content://synthetic/video"));set(it,"primaryDurationMs",5000L);set(it,"accessMode",EditorAccessMode.GUEST_BASIC);set(it,"workspaceActive",true);set(it,"importedSources",linkedMapOf<String,VideoSource>())}
 private fun showing(d:AlertDialog,value:Boolean){android.app.Dialog::class.java.getDeclaredField("mDecor").apply{isAccessible=true}.set(d,if(value)unsafe.allocateInstance(android.view.View::class.java)else null)}
 private fun dialog()=(unsafe.allocateInstance(AlertDialog::class.java)as AlertDialog).also{showing(it,true)}
 private fun capture(a:HonorableVideoEditorActivity)=call(a,"captureCaptionReview")as VideoCaptionReviewState
 private fun transformActivity():HonorableVideoEditorActivity=activity().also{a->val p=get(a,"project")as VideoEditProject;val first=p.segments[0].copy(title="Rotated",layout=VideoLayout(4,true,270,true,false),grade=VideoGrade(exposure=.4f));p.restore(listOf(first,first.copy(startMs=1000,endMs=4000,speed=2f,title="Other",layout=VideoLayout(rotation=90,mirrorY=true))),soundtrack=p.soundtrack)}
 private fun editor(a:HonorableVideoEditorActivity):AlertDialog=dialog().also{set(a,"inspectorReviewDialog",it);set(a,"captionReviewDialogs",linkedSetOf(it))}
 private fun commit(a:HonorableVideoEditorActivity,d:AlertDialog,r:VideoCaptionReviewState,choice:Int=0):Boolean {val p=get(a,"project")as VideoEditProject;return call(a,"commitTransformReview",d,r,p,0,p.segments[0],choice)as Boolean}
 @Test fun rotationWrapsAndOnlyChangesSelectedLayoutWithOneUndo(){val a=transformActivity();val p=get(a,"project")as VideoEditProject;val old=p.segments;val music=p.soundtrack;val duration=VideoPlaybackTime.durationUs(old);val r=capture(a);val d=editor(a);assertTrue(commit(a,d,r));assertEquals(old[0].copy(layout=old[0].layout.copy(rotation=0)),p.segments[0]);assertSame(old[1],p.segments[1]);assertSame(music,p.soundtrack);assertEquals(duration,VideoPlaybackTime.durationUs(p.segments));assertNull(get(a,"inspectorReviewDialog"));assertTrue(p.undo());assertEquals(old,p.segments);assertFalse(p.canUndo);assertTrue(p.redo());assertEquals(0,p.segments[0].layout.rotation)}
 @Test fun flipsAndResetKeepRatioCropOtherClipSettingsAndMusic(){for(choice in listOf(1,2,3)){val a=transformActivity();val p=get(a,"project")as VideoEditProject;val old=p.segments;val music=p.soundtrack;val l=old[0].layout;val expected=when(choice){1->l.copy(mirrorX=false);2->l.copy(mirrorY=true);else->l.copy(rotation=0,mirrorX=false,mirrorY=false)};val r=capture(a);val d=editor(a);assertTrue(commit(a,d,r,choice));assertEquals(old[0].copy(layout=expected),p.segments[0]);assertSame(old[1],p.segments[1]);assertSame(music,p.soundtrack);assertTrue(p.undo());assertEquals(old,p.segments);assertFalse(p.canUndo)}}
 @Test fun noOpResetAndInvalidChoicesCannotChangeHistory(){val a=transformActivity();val p=get(a,"project")as VideoEditProject;p.restore(p.segments.mapIndexed{i,c->if(i==0)c.copy(layout=VideoLayout(4,true))else c},soundtrack=p.soundtrack);val old=p.segments;val r=capture(a);val d=editor(a);assertFalse(commit(a,d,r,3));assertSame(old,p.segments);assertFalse(p.canUndo);assertNull(get(a,"inspectorReviewDialog"));for(choice in listOf(-1,4)){val b=transformActivity();val q=get(b,"project")as VideoEditProject;val before=q.segments;val current=editor(b);val review=capture(b);try{commit(b,current,review,choice);fail("Accepted invalid choice")}catch(e:java.lang.reflect.InvocationTargetException){assertTrue(e.cause is IllegalArgumentException)};assertSame(before,q.segments);assertFalse(q.canUndo)}}
 @Test fun untrackedDismissedOrReplacedPickerCannotApply(){for(flag in listOf("untracked","dismissed","replaced")){val a=transformActivity();val p=get(a,"project")as VideoEditProject;val old=p.segments;val r=capture(a);val d=editor(a);when(flag){"untracked"->set(a,"captionReviewDialogs",linkedSetOf<AlertDialog>());"dismissed"->showing(d,false);else->set(a,"inspectorReviewDialog",dialog())};assertFalse(flag,commit(a,d,r));assertSame(old,p.segments);assertFalse(p.canUndo)}}
 @Test fun staleForegroundGenerationSourceRangeSessionRecoveryAndMusicReject(){for(flag in listOf("pause","generation","source","duration","range","mode","recovery","busy","analysis","music")){val a=transformActivity();val p=get(a,"project")as VideoEditProject;val r=capture(a);val d=editor(a);when(flag){"pause"->set(a,"workspaceActive",false);"generation"->set(a,"captionReviewGeneration",r.generation+1);"source"->set(a,"source",Uri.parse("content://synthetic/other"));"duration"->set(a,"primaryDurationMs",5001L);"range"->set(a,"selectedClip",1);"mode"->set(a,"accessMode",EditorAccessMode.ACCOUNT);"recovery"->set(a,"recoveryBytes",byteArrayOf(1));"busy"->set(a,"saving",true);"analysis"->set(a,"analyzing",true);else->p.setSoundtrack(p.soundtrack!!.copy(volume=.5f))};val before=p.segments;assertFalse(flag,commit(a,d,r));assertSame(before,p.segments);assertNull(get(a,"inspectorReviewDialog"))}}
 @Test fun oldOwnerCannotConsumeNewOrReviveAfterUndo(){val a=transformActivity();val p=get(a,"project")as VideoEditProject;val old=editor(a);val current=editor(a);val r=capture(a);assertFalse(commit(a,old,r,3));assertSame(current,get(a,"inspectorReviewDialog"));assertTrue(commit(a,current,r));assertFalse(commit(a,current,r));assertTrue(p.undo());assertEquals(true,call(a,"canApplyCaptionReview",r));assertFalse(commit(a,current,r));assertFalse(p.canUndo);assertTrue(p.canRedo)}
 @Test fun selectedTransformAndAllOtherMetadataSurviveExistingCodec(){val a=transformActivity();val p=get(a,"project")as VideoEditProject;val r=capture(a);val d=editor(a);assertTrue(commit(a,d,r,0));val draft=VideoDraft(5000,p.segments,0,0,0,5000,soundtrack=p.soundtrack);val restored=requireNotNull(VideoDraftCodec.decode(VideoDraftCodec.encode(draft),5000));assertEquals(draft,restored);assertEquals(VideoLayout(4,true,0,true,false),restored.segments[0].layout);assertEquals(VideoLayout(rotation=90,mirrorY=true),restored.segments[1].layout);assertEquals("content://synthetic/subtitles",restored.segments[0].captionSourceUri)}
 @Test fun pausedOrRecoveringTransformEntryReturnsBeforeWidgets(){for(recovery in listOf(false,true)){val a=transformActivity();if(recovery)set(a,"recoveryBytes",byteArrayOf(1))else set(a,"workspaceActive",false);call(a,"transformVideo");assertNull(get(a,"inspectorReviewDialog"));assertNull(get(a,"captionReviewDialogs"));assertFalse((get(a,"project")as VideoEditProject).canUndo)}}
}
